"""Source-fact procedural Tenshouki fixtures; no generated bytes called genuine."""
from dataclasses import replace
from functools import lru_cache
import hashlib
import json
import os
from pathlib import Path
import struct
import tempfile
import unittest
from unittest.mock import patch

from koei_editor.games.dw3.models import SaveError
from koei_editor.games.nobu6_pk_pc import parser


@lru_cache(maxsize=1)
def generated_raw():
    raw = bytearray((i * 31 + 17) % 256 for i in range(parser.SIZE))
    raw[:11] = parser.MAGIC
    for slot in range(parser.SLOT_COUNT):
        struct.pack_into('<H', raw, 11 + slot * 2, int(slot in (0, 7)))
        if slot not in (0, 7):
            continue
        preview = 0x1F + slot * 158
        struct.pack_into('<H', raw, preview, 80)
        raw[preview + 2] = 1
        raw[preview + 16:preview + 18] = bytes((0, 2))
        origin = parser.SLOT_START + slot * parser.SLOT_SIZE
        raw[origin + 2] = 2  # Preview and actual season are distinct.
        for index in range(parser.DISTRICT_COUNT):
            base = origin + parser.DISTRICT_START + index * parser.DISTRICT_SIZE
            struct.pack_into('<H', raw, base + 4, 0xFFFF)
        for index in range(parser.CLAN_COUNT):
            struct.pack_into('<H', raw, origin + parser.CLAN_START + index * parser.CLAN_SIZE, 0xFFFF)
        for index in (0, 213):
            base = origin + parser.DISTRICT_START + index * parser.DISTRICT_SIZE
            struct.pack_into('<HHH', raw, base + 4, index + 1, 1, 1)
            for key, label, relative in parser.RESOURCE_FIELDS:
                struct.pack_into('<H', raw, base + relative, 1000 + index + slot)
        struct.pack_into('<H', raw, origin + parser.CLAN_START, 1)
        names = origin + parser.NAME_START
        raw[names:names + 14] = b'ODA\0xyzNOBU\0ab'
        raw[origin + parser.CASTLE_START + 8:origin + parser.CASTLE_START + 17] = b'KIYOSU\0xy'
    return bytes(raw)


class Nobu6SourceQualifiedTests(unittest.TestCase):
    def setUp(self):
        self.document = parser.decode(generated_raw())

    def test_explicit_source_qualification_and_byte_exact_noop(self):
        self.assertTrue(self.document.format.published_format)
        self.assertFalse(self.document.format.sample_verified)
        self.assertFalse(self.document.format.editing_verified)
        self.assertFalse(self.document.format.game_load_verified)
        self.assertEqual(parser.serialize(self.document, {}), generated_raw())
        self.assertEqual(len(parser.fields_for(self.document)), 16)
        self.assertEqual(len(parser.inspection_rows(self.document)[0]), 8)
        self.assertEqual(len(parser.inspection_rows(self.document)[1]), 4)
        self.assertEqual(len(parser.inspection_rows(self.document)[2]), 1064)

    def test_every_source_mapped_resource_is_surgical_and_other_slots_preserved(self):
        for field in parser.fields_for(self.document):
            with self.subTest(field=field.id):
                edited = parser.serialize(self.document, {field.id: 0})
                changed = {i for i, (a, b) in enumerate(zip(self.document.raw, edited)) if a != b}
                self.assertTrue(changed)
                self.assertLessEqual(changed, {field.offset, field.offset + 1})
                self.assertEqual(parser.decode(edited).raw, edited)
        changes = {field.id: 0 for field in parser.fields_for(self.document)}
        self.assertEqual(len(parser.review(self.document, changes)), 16)
        edited = parser.serialize(self.document, changes)
        for slot in range(1, 7):
            origin = parser.SLOT_START + slot * parser.SLOT_SIZE
            self.assertEqual(edited[origin:origin + parser.SLOT_SIZE], self.document.raw[origin:origin + parser.SLOT_SIZE])
        self.assertEqual(edited[:parser.SLOT_START], self.document.raw[:parser.SLOT_START])

    def test_no_stock_creation_max_or_unusual_value_normalization(self):
        key = parser.fields_for(self.document)[0].id
        field = parser.field_map(self.document)[key]
        raw = bytearray(generated_raw())
        struct.pack_into('<H', raw, field.offset, 65535)
        high = parser.decode(raw)
        changes = parser.stage(high, {}, key, 2)
        self.assertEqual(parser.maximums(high, changes), changes)
        self.assertEqual(parser.limit_values(high, changes, [key]), {})
        self.assertEqual(parser.stage(high, changes, key, 65535), {})
        self.assertFalse(parser.field_map(high)[key].maxable)
        struct.pack_into('<H', raw, field.offset, 0)
        empty = parser.decode(raw)
        self.assertNotIn(key, parser.field_map(empty))
        with self.assertRaises(SaveError):
            parser.stage(empty, {}, key, 1)

    def test_invalid_types_context_snapshot_and_source_field_bounds(self):
        key = parser.fields_for(self.document)[0].id
        for value in (-1, 65536, 1001, True, 3.5, '1', None):
            with self.subTest(value=value), self.assertRaises(SaveError):
                parser.stage(self.document, {}, key, value)
        for changes in ({'slot_1_district_0_gold': 0}, {'year': 1}, {key: True}, [], None):
            with self.assertRaises(SaveError):
                parser.serialize(self.document, changes)
        for key in ([], {}, True, None):
            with self.assertRaises(SaveError):
                parser.stage(self.document, {}, key, 0)
            with self.assertRaises(SaveError):
                parser.limit_values(self.document, {}, [key])
        for forged in (replace(self.document, format=replace(parser.FORMAT)),
                       replace(self.document, source=None),
                       replace(self.document, source=[]),
                       replace(self.document, raw=bytearray(self.document.raw)),
                       replace(self.document, payload=b'x' * parser.SIZE)):
            with self.assertRaises(SaveError):
                parser.serialize(forged, {})
        with self.assertRaises(SaveError):
            parser.decode(generated_raw(), 'nobu6_hd')

    def test_exact_framing_and_occupied_record_reference_rejection(self):
        for raw in (generated_raw()[:-1], generated_raw() + b'x', b'\0' * parser.SIZE,
                    memoryview(generated_raw())):
            with self.assertRaises(SaveError):
                parser.decode(raw)
        for offset, data in ((11, b'\x02\0'), (0x1F + 2, b'\x04'),
                             (0x1F + 16, b'\x06'), (0x1F + 17, b'\x05'),
                             (parser.SLOT_START + 2, b'\x04'),
                             (parser.SLOT_START + parser.DISTRICT_START + 4, b'\0\0'),
                             (parser.SLOT_START + parser.DISTRICT_START + 6, b'\x15\x02'),
                             (parser.SLOT_START + parser.DISTRICT_START + 8, b'\x49\0'),
                             (parser.SLOT_START + parser.CLAN_START, b'\xff\xff')):
            raw = bytearray(generated_raw())
            raw[offset:offset + len(data)] = data
            with self.subTest(offset=offset), self.assertRaises(SaveError):
                parser.decode(raw)

    def test_safe_saving_backups_restore_source_race_and_live_game_rejection(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            source, target, restored = (root / name for name in ('copy.n6p', 'edited.n6p', 'restored.n6p'))
            source.write_bytes(generated_raw())
            document = parser.read_save(source)
            key = parser.fields_for(document)[0].id
            saved = parser.save_as(document, {key: 0}, target)
            self.assertEqual(source.read_bytes(), document.raw)
            self.assertEqual(saved.raw, parser.serialize(document, {key: 0}))
            backup = parser.backup(document)
            parser.restore(backup, restored)
            self.assertEqual(restored.read_bytes(), document.raw)
            with self.assertRaises(FileExistsError):
                parser.save_as(document, {}, source)
            with self.assertRaises(FileExistsError):
                parser.restore(backup, restored)
            original_backup = parser.snapshot_backup

            def race(*args, **kwargs):
                result = original_backup(*args, **kwargs)
                source.write_bytes(b'changed while backing up')
                return result

            with patch.object(parser, 'snapshot_backup', side_effect=race):
                with self.assertRaises(SaveError):
                    parser.save_as(document, {}, root / 'race.n6p')
            self.assertFalse((root / 'race.n6p').exists())
            source.write_bytes(document.raw)
            forged = bytearray(document.raw)
            forged[:11] = b'wrongheader'
            backup.write_bytes(forged)
            metadata = json.loads(backup.with_suffix('.json').read_text())
            metadata['sha256'] = hashlib.sha256(forged).hexdigest()
            backup.with_suffix('.json').write_text(json.dumps(metadata))
            with self.assertRaises(SaveError):
                parser.restore(backup, root / 'badrestore.n6p')
            self.assertFalse((root / 'badrestore.n6p').exists())
            (root / 'TEN95PK.EXE').write_bytes(b'not executable; live-path guard fixture')
            with self.assertRaises(SaveError):
                parser.read_save(source)
            with self.assertRaises(SaveError):
                parser.restore(backup, root / 'live.n6p')
            (root / 'TEN95PK.EXE').unlink()
            (root / 'tenshou.exe').write_bytes(b'source-named live-path guard fixture')
            with self.assertRaises(SaveError):
                parser.read_save(source)
            with self.assertRaises(SaveError):
                parser.save_as(document, {}, root / 'live-tenshou.n6p')
            with self.assertRaises(SaveError):
                parser.restore(backup, root / 'live-tenshou-restore.n6p')

    def test_no_opaque_name_or_owner_record_normalization(self):
        raw = bytearray(generated_raw())
        name = parser.SLOT_START + parser.NAME_START
        raw[name:name + 7] = b'\x81\0\x17\0abc'
        document = parser.decode(raw)
        self.assertIn('native name bytes', parser.inspection_rows(document)[2][0][2])
        self.assertEqual(parser.serialize(document, {}), bytes(raw))
        key = parser.fields_for(document)[0].id
        self.assertEqual(parser.serialize(document, {key: 0})[name:name + 7], bytes(raw[name:name + 7]))

    def test_symbolic_and_hard_link_source_destination_and_restore_rejection(self):
        with tempfile.TemporaryDirectory() as temporary:
            folder = Path(temporary)
            source = folder / 'copy.n6p'
            source.write_bytes(generated_raw())
            document = parser.read_save(source)
            linked = folder / 'linked.n6p'
            os.link(source, linked)
            with self.assertRaises(SaveError):
                parser.read_save(linked)
            with self.assertRaises(SaveError):
                parser.save_as(document, {}, folder / 'hardlink-edited.n6p')
            linked.unlink()
            backup = parser.backup(document)
            # Symlink creation may require privileges on Windows; hard-link
            # protections above always execute, even on such hosts.
            try:
                linked.symlink_to(source)
            except OSError:
                return
            with self.assertRaises(SaveError):
                parser.read_save(linked)
            alias_folder = folder / 'alias'
            alias_folder.symlink_to(folder, target_is_directory=True)
            with self.assertRaises(SaveError):
                parser.save_as(document, {}, alias_folder / 'edited.n6p')
            with self.assertRaises(SaveError):
                parser.restore(backup, alias_folder / 'restored.n6p')
            backup_alias = folder / 'backup-alias.n6p'
            backup_alias.symlink_to(backup)
            with self.assertRaises(SaveError):
                parser.restore(backup_alias, folder / 'restored.n6p')

    @unittest.skipUnless(os.name == 'nt' or os.environ.get('DISPLAY'), 'Graphical display required')
    def test_actual_tk_open_stage_undo_review_save_as_restore(self):
        import tkinter as tk
        from koei_editor.games.nobu6_pk_pc.editor import Editor
        root = tk.Tk()
        root.withdraw()
        try:
            with tempfile.TemporaryDirectory() as temporary:
                folder = Path(temporary)
                source, target = folder / 'copy.n6p', folder / 'edited.n6p'
                source.write_bytes(generated_raw())
                editor = Editor(root)
                with patch('koei_editor.shared.verified_gui.filedialog.askopenfilename', return_value=str(source)), \
                     patch('koei_editor.shared.verified_gui.messagebox.showerror') as errors:
                    editor.open()
                    errors.assert_not_called()
                self.assertEqual(len(editor.presentation.inspection_tables(editor.document)), 6)
                field = parser.fields_for(editor.document)[0]
                editor.fields.selection_set(field.id)
                editor.value.set('0')
                editor.apply_selected()
                self.assertEqual(editor.changes, {field.id: 0})
                editor.undo()
                self.assertEqual(editor.changes, {})
                editor.value.set('0')
                editor.apply_selected()
                editor.review()
                next(w for w in root.winfo_children() if isinstance(w, tk.Toplevel)).destroy()
                editor.apply_theme('Dark')
                with patch('koei_editor.shared.verified_gui.filedialog.asksaveasfilename', return_value=str(target)), \
                     patch('koei_editor.shared.verified_gui.messagebox.showerror') as errors:
                    editor.save_as()
                    errors.assert_not_called()
                self.assertEqual(target.read_bytes(), parser.serialize(parser.read_save(source), {field.id: 0}))
                backup = next((folder / 'WarriorsEditorBackups').glob('*.n6p'))
                restored = folder / 'restored.n6p'
                with patch('koei_editor.shared.verified_gui.filedialog.askopenfilename', return_value=str(backup)), \
                     patch('koei_editor.shared.verified_gui.filedialog.asksaveasfilename', return_value=str(restored)), \
                     patch('koei_editor.shared.verified_gui.messagebox.showerror') as errors:
                    editor.restore()
                    errors.assert_not_called()
                self.assertEqual(restored.read_bytes(), generated_raw())
        finally:
            root.destroy()
